    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = True
    if len(adj[0]) != n:
        is_matrix = False
    else:
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and degree list
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        degree = [len(adj_list[i]) for i in range(n)]
    else:
        adj_list = [list(neighbors) for neighbors in adj]
        degree = [len(adj_list[i]) for i in range(n)]

    # Welsh-Powell ordering (descending degree)
    order = sorted(range(n), key=lambda x: (-degree[x], x))

    # Greedy coloring with Welsh-Powell order
    color = [-1] * n
    for v in order:
        used = [False] * n
        for u in adj_list[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color[v] = c

    k = max(color) + 1 if n > 0 else 0

    # Kempe chain local search to reduce colors
    improved = True
    while improved and k > 1:
        improved = False
        # Process color classes from highest to lowest
        for target_color in range(k - 1, 0, -1):
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                continue
            random.shuffle(vertices)
            for v in vertices:
                # Try to move v to a lower color directly
                neighbor_colors = set()
                for u in adj_list[v]:
                    if color[u] < target_color:
                        neighbor_colors.add(color[u])
                for c in range(target_color):
                    if c not in neighbor_colors:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap for each lower color
                for c in range(target_color):
                    # BFS to find the (target_color, c)-Kempe chain containing v
                        stack = [v]
                        visited = [False] * n
                        visited[v] = True
                        component = []
                        while stack:
                            node = stack.pop()
                            component.append(node)
                            for nb in adj_list[node]:
                                if not visited[nb] and color[nb] in (target_color, c):
                                    visited[nb] = True
                                    stack.append(nb)
                        # Check if any neighbor of the component has color c
                        has_c_neighbor = False
                        for node in component:
                            for nb in adj_list[node]:
                                if color[nb] == c:
                                    has_c_neighbor = True
                                    break
