                            # Swap colors in the component
                            for node in component:
                                if color[node] == target_color:
                                    color[node] = c
                                else:
                                    color[node] = target_color
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break
        if improved:
            k -= 1
            # Rebuild color set for next iteration
            k = max(color) + 1 if n > 0 else 0
        else:
            break

    return color

