def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []

    n = len(adj)

    # Detect adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1
        all_binary = True
        for i in range(n):
            if len(adj[i]) != n:
                all_binary = False
                break
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for fast lookup
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            for nb in adj[i]:
                if 0 <= nb < n:
                    neighbors[i].add(nb)

    # Handle trivial cases
    if n == 1:
        return [0]

    # Check for edgeless graph
    has_edge = any(len(neighbors[i]) > 0 for i in range(n))
    if not has_edge:
        return [0] * n

    # Check for complete graph
    is_complete = True
    for i in range(n):
        if len(neighbors[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))

    # Degeneracy ordering (smallest-last)
    def degeneracy_ordering():
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        buckets = [[] for _ in range(n)]
        max_deg = max(deg) if n > 0 else 0
        for v in range(n):
            if deg[v] < len(buckets):
                buckets[deg[v]].append(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr < len(buckets) and not buckets[ptr]:
                ptr += 1
            if ptr >= len(buckets):
                break  # Should not happen
            v = buckets[ptr].pop()
            # It's possible that v was already removed or degree changed, check
            if v not in remaining:
                # Need to find another vertex, restart search for this iteration
                # Re-scan from ptr
                found = False
                for d in range(ptr, len(buckets)):
                    if buckets[d]:
                        v = buckets[d].pop()
                        if v in remaining:
                            found = True
                            ptr = d
                            break
                if not found:
                    break
            remaining.remove(v)
            order.append(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d_u = deg[u]
                    # Remove u from its current bucket
                    if d_u < len(buckets) and u in buckets[d_u]:
                        buckets[d_u].remove(u)
                    deg[u] -= 1
                    d_u_new = deg[u]
                    if d_u_new < len(buckets):
                        buckets[d_u_new].append(u)
                    # Update ptr if needed
                    if d_u_new < ptr:
                        ptr = d_u_new
        return order[::-1]  # Reverse to get coloring order

    order = degeneracy_ordering()
    pos = [0] * n
    for idx, v in enumerate(order):
        pos[v] = idx

    # Greedy coloring in degeneracy order
    color = [-1] * n
    max_color_used = 0
    for v in order:
        used = [False] * (max_color_used + 2)  # +2 for safety
        for u in neighbors[v]:
            c = color[u]
            if c != -1 and c < len(used):
                used[c] = True
        c = 0
        while c < len(used) and used[c]:
            c += 1
        color[v] = c
        if c > max_color_used:
            max_color_used = c

    k = max_color_used + 1

    # Try to improve with Kempe chain swaps
    improved = True
    # Limit iterations to avoid timeout
    for _ in range(10):  # Max 10 rounds
        if not improved:
            break
        improved = False
        # Build color classes
        color_classes = [[] for _ in range(k)]
        for v in range(n):
            if color[v] < k:
                color_classes[color[v]].append(v)
        # Try to eliminate color classes from highest to lowest
        for c in range(k-1, 0, -1):
            if not color_classes[c]:
                continue
            # Try to recolor each vertex in color c
            recolored = [False] * len(color_classes[c])
            # We'll try to move vertices to lower colors
            for idx, v in enumerate(color_classes[c]):
                if recolored[idx]:
                    continue
                # Try direct move to a lower color
                moved = False
                for c2 in range(c):
                    # Check if v can take color c2
                    conflict = False
                    for u in neighbors[v]:
                        if color[u] == c2:
                            conflict = True
                            break
                    if not conflict:
                        # Move v to color c2
                        color[v] = c2
                        color_classes[c].pop(idx)
                        color_classes[c2].append(v)
                        moved = True
                        improved = True
                        break
                if moved:
                    # After moving, we need to restart the scan for this color class
                    # because indices changed
                    break
                # Try Kempe chains with each lower color
                for c2 in range(c):
                    # We'll try to find a Kempe chain (c, c2) starting from v
                    # that does not include any other vertex of color c that we want to keep
                    # Use BFS to find the component
                    visited = [False] * n
                    stack = [v]
                    visited[v] = True
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for u in neighbors[node]:
                            if not visited[u] and (color[u] == c or color[u] == c2):
                                visited[u] = True
                                stack.append(u)
                    # Check if this component contains any other vertex of color c (besides v)
                    has_other_c = False
                    for node in component:
                        if node != v and color[node] == c:
                            has_other_c = True
                            break
                    if not has_other_c:
                        # Swap colors c and c2 in the component
                        for node in component:
                            if color[node] == c:
                                color[node] = c2
                            elif color[node] == c2:
                                color[node] = c
                        # Update color classes: need to rebuild or update incrementally
                        # For simplicity, we'll rebuild color classes after any Kempe swap
                        improved = True
                        break
                    # If we tried a Kempe chain, break to restart scan
                    if not has_other_c:
                        break
                if improved:
                    break
            if improved:
                # Rebuild color classes for next iteration
                break
        # If we improved, rebuild color classes and try again
        if improved:
            # Recompute k and color classes
            max_color = max(color) if n > 0 else -1
            k = max_color + 1
            # Ensure k is at least 1
            if k < 1:
                k = 1

    # Final validation (optional, but ensures correctness)
    # We'll do a quick check and fix if needed (should not happen)
    for v in range(n):
        for u in neighbors[v]:
            if color[v] == color[u]:
                # Conflict, fix by assigning a new color (should be rare)
                used = [False] * (n + 1)
                for w in neighbors[v]:
                    if color[w] != -1:
                        used[color[w]] = True
                c = 0
                while c < len(used) and used[c]:
                    c += 1
                color[v] = c
                if c >= k:
                    k = c + 1

    # Ensure colors are in range [0, k-1]
    # Relabel colors to be consecutive if needed (not strictly required but nice)
    # But we already keep them consecutive via the algorithm
    return color

