def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True

    # Build adjacency list and compute degrees
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        deg = [len(adj_list[i]) for i in range(n)]
    else:
        adj_list = adj
        deg = [len(adj_list[i]) for i in range(n)]

    # Handle trivial cases
    if n == 1:
        return [0]
    if all(d == 0 for d in deg):
        return [0] * n
    if all(d == n - 1 for d in deg):
        return list(range(n))

    # DSATUR algorithm
    color = [-1] * n
    saturation = [set() for _ in range(n)]
    uncolored = set(range(n))

    # Initial vertex: highest degree, tie-break by index
    v = max(uncolored, key=lambda x: (deg[x], -x))
    color[v] = 0
    uncolored.remove(v)
    for u in adj_list[v]:
        if u in uncolored:
            saturation[u].add(0)

    # Color remaining vertices
    while uncolored:
        # Select vertex with max saturation degree, tie-break by degree in uncolored subgraph, then index
        v = max(uncolored, key=lambda x: (
            len(saturation[x]),
            sum(1 for u in adj_list[x] if u in uncolored),
            -x
        ))
        # Find smallest available color
        used = saturation[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c
        uncolored.remove(v)
        # Update saturation of uncolored neighbors
        for u in adj_list[v]:
            if u in uncolored:
                saturation[u].add(c)

    k = max(color) + 1 if n > 0 else 0

    # Try to improve using Kempe chain-based color class elimination
    improved = True
    while improved and k > 1:
        improved = False
        # Build color classes
        color_classes = [[] for _ in range(k)]
        for v in range(n):
            color_classes[color[v]].append(v)
        # Find smallest non-empty color class
        c_min = None
        min_size = float('inf')
        for c in range(k):
            if color_classes[c] and len(color_classes[c]) < min_size:
                min_size = len(color_classes[c])
                c_min = c
        if c_min is None:
            break
        # Try to eliminate color c_min
        eliminated = [True] * len(color_classes[c_min])
        for idx, v in enumerate(color_classes[c_min]):
            # Try to move v to a lower color directly
            moved = False
            for c in range(c_min):
                conflict = False
                for u in adj_list[v]:
                    if color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    # Move v to color c
                    color[v] = c
                    color_classes[c].append(v)
                    eliminated[idx] = False
                    moved = True
                    break
            if moved:
                continue
            # Try Kempe chains for each lower color
            for c in range(c_min):
                # BFS to find the (c, c_min)-Kempe chain containing v
                visited = [False] * n
                stack = [v]
                visited[v] = True
                component = []
                while stack:
                    node = stack.pop()
                    component.append(node)
                    for u in adj_list[node]:
                        if not visited[u] and (color[u] == c or color[u] == c_min):
                            visited[u] = True
                            stack.append(u)
                # Check if this component has no vertex of color c (other than possibly v, but v is c_min)
                has_c = any(color[u] == c for u in component)
                if not has_c:
                    # Swap colors c and c_min in the component
                    for u in component:
                        if color[u] == c_min:
                            color[u] = c
                        elif color[u] == c:
                            color[u] = c_min
                    # Update color classes: remove v from c_min, add to c
                    color_classes[c_min].remove(v)
                    color_classes[c].append(v)
                    eliminated[idx] = False
                    moved = True
                    break
            if moved:
                improved = True
                break  # Break color loop after moving one vertex
        if improved:
            # Rebuild color classes and possibly reduce k
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[color[v]].append(v)
            # Find new maximum color used
            new_k = 0
            for c in range(k):
                if color_classes[c]:
                    new_k = max(new_k, c + 1)
            if new_k < k:
                k = new_k
                improved = True  # Continue to try further reduction
            else:
                # No reduction in k, but we made a move; continue to see if we can reduce later
                pass
        else:
            # No improvement in this round
            break

    return color

