def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj[0]) == n:
        if all(isinstance(x, int) and x in (0, 1) for row in adj for x in row):
            is_matrix = True
    if is_matrix:
        neighbors = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        neighbors = [list(lst) for lst in adj]

    # Precompute degree for each vertex
    degree = [len(neighbors[i]) for i in range(n)]

    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree then index
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if not colored[u]:
                    if sat[u] > max_sat or (sat[u] == max_sat and degree[u] > max_deg) or \
                       (sat[u] == max_sat and degree[u] == max_deg and u > v):
                        max_sat = sat[u]
                        max_deg = degree[u]
                        v = u
            if v == -1:
                break  # should not happen
            # Assign smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    sat[u] += 1
        return color

    def rlf():
        color = [-1] * n
        colored = [False] * n
        c = 0
        while not all(colored):
            # Build maximal independent set for color c
            S = []
            U = [i for i in range(n) if not colored[i]]
            W = []
            if not U:
                break
            # Start with vertex of max degree in U
            v = max(U, key=lambda x: degree[x])
            S.append(v)
            U.remove(v)
            colored[v] = True
            # Move neighbors of v from U to W
            for u in neighbors[v]:
                if not colored[u] and u in U:
                    U.remove(u)
                    W.append(u)
            # Expand S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in neighbors[u] if not colored[nb] and nb in W)
                    deg_in_U = sum(1 for nb in neighbors[u] if not colored[nb] and nb in U)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and u < best_u):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break  # should not happen
                S.append(best_u)
                U.remove(best_u)
                colored[best_u] = True
                # Move neighbors of best_u from U to W
                for u in neighbors[best_u]:
                    if not colored[u] and u in U:
                        U.remove(u)
                        W.append(u)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    def smallest_last():
        # Compute degeneracy ordering (smallest-last)
        remaining = set(range(n))
        order = []
        deg = degree[:]  # current degree in remaining subgraph
        while remaining:
            # Find vertex with minimum degree in remaining
            v = min(remaining, key=lambda x: deg[x])
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    deg[u] -= 1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    def welsh_powell():
        # Sort by degree descending
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        return greedy_color(order)

    def kempe_improve(color_in):
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        if k <= 1:
            return color
        improved = True
        while improved and k > 1:
            improved = False
            # Try to eliminate color k-1
            target_color = k - 1
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                k -= 1
                continue
            # Try to recolor each vertex in target_color
            for v in vertices:
                # Try direct recolor to a lower color
                used = [False] * k
                for u in neighbors[v]:
                    if color[u] < k:
                        used[color[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains
                for c in range(target_color):
                    # Skip if v already has a neighbor of color c (would cause conflict if added)
                    has_c_neighbor = any(color[u] == c for u in neighbors[v])
                    if has_c_neighbor:
                        continue
                    # Build Kempe chain for colors (target_color, c) starting from v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if color[node] == target_color or color[node] == c:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (color[nb] == target_color or color[nb] == c):
                                    stack.append(nb)
                    # Check if any neighbor of v in the component has color c
                    # If yes, swapping would cause v to have a neighbor of color c after swap
                    conflict = False
                    for node in component:
                        if node != v and color[node] == c:
                            for nb in neighbors[node]:
                                if nb == v:
                                    conflict = True
                                    break
                            if conflict:
                                break
                    if not conflict:
                        # Perform swap
                        for node in component:
                            if color[node] == target_color:
                                color[node] = c
                            elif color[node] == c:
                                color[node] = target_color
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                break
            # Recompute k after attempts
            k = max(color) + 1
        return color

    # Generate initial colorings
    colorings = []
    colorings.append(dsatur())
    colorings.append(rlf())
    colorings.append(smallest_last())
    colorings.append(welsh_powell())

    # Select the coloring with the fewest colors
    best_color = min(colorings, key=lambda c: max(c) + 1 if n > 0 else 0)
    # Apply Kempe chain improvement
    best_color = kempe_improve(best_color)
    return best_color

