                        break
                if new:
                    sat[nb] += 1
    # Try to improve by removing color classes via Kempe chains
    def kempe_chain(start, color_a, color_b, visited, comp):
        stack = [start]
        visited.add(start)
        comp.add(start)
        while stack:
            v = stack.pop()
            for nb in neighbors[v]:
                if nb not in visited and (color[nb] == color_a or color[nb] == color_b):
                    visited.add(nb)
                    comp.add(nb)
                    stack.append(nb)
    max_color = max(color) if color else -1
    improved = True
    while improved and max_color > 0:
        improved = False
        # try to eliminate the last color class
        target_color = max_color
        # vertices with target_color
        target_vertices = [v for v in range(n) if color[v] == target_color]
        if not target_vertices:
            max_color -= 1
