                u = best_u
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return coloring

    # Helper: Welsh-Powell (largest first)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: degrees[x], reverse=True)
        return greedy_coloring(order)

    # Helper: Smallest-Last ordering
    def smallest_last():
        # Compute degeneracy ordering
        remaining = set(range(n))
        order = []
        # current degrees in remaining graph
        deg = degrees[:]
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # pointer to current non-empty bucket
        ptr = 0
        while remaining:
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if u in remaining:
                    # remove u from its current bucket
                    old_deg = deg[u]
                    buckets[old_deg].remove(u)
                    deg[u] -= 1
                    new_deg = deg[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].append(u)
                    else:
                        # should not happen as degree decreases
                        pass
                    if new_deg < ptr:
                        ptr = new_deg
        # color in reverse order
        return greedy_coloring(order[::-1])

    # Try multiple algorithms and pick the best valid coloring
    algorithms = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Welsh-Powell", welsh_powell),
        ("Smallest-Last", smallest_last),
    ]

    best_coloring = None
    best_colors = float('inf')

    for name, alg in algorithms:
        try:
            coloring = alg()
            # Validate
            if is_valid_coloring(coloring):
                colors_used = max(coloring) + 1 if n > 0 else 0
                if colors_used < best_colors:
                    best_colors = colors_used
                    best_coloring = coloring
                    # Early exit if we found optimal (lower bound: clique number)
                    # Compute a simple lower bound: max degree + 1 is an upper bound, but we use greedy
                    # For speed, we can stop if we hit 1 (only possible for edgeless) or 2 (bipartite) but not trivial
        except Exception:
            # In case of any error, skip this algorithm
            continue

    # Fallback: if no algorithm produced a valid coloring (should not happen), use greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_coloring(list(range(n)))

    return best_coloring

