        neighbors = [ [j for j, val in enumerate(row) if val] for row in adj ]
    else:
        neighbors = [ list(lst) for lst in adj ]
        # Ensure undirected and no self-loops
        for u in range(n):
            for v in neighbors[u]:
                if u == v:
                    neighbors[u].remove(v)
                if u not in neighbors[v]:
                    neighbors[v].append(u)
        # Deduplicate
        for u in range(n):
            neighbors[u] = list(set(neighbors[u]))

    # DSATUR with Kempe chain refinement
    color = [-1] * n
    sat = [0] * n  # saturation degree
    colored_neighbors = [set() for _ in range(n)]

    # Helper: get uncolored vertex with max saturation, tie-break by degree in uncolored subgraph
    def select_vertex():
        max_sat = -1
        candidates = []
        for v in range(n):
            if color[v] == -1:
                if sat[v] > max_sat:
                    max_sat = sat[v]
                    candidates = [v]
                elif sat[v] == max_sat:
                    candidates.append(v)
        if not candidates:
            return -1
        # Tie-break: max degree in uncolored subgraph
        max_deg = -1
        best = candidates[0]
        for v in candidates:
            deg = sum(1 for u in neighbors[v] if color[u] == -1)
            if deg > max_deg:
                max_deg = deg
                best = v
            elif deg == max_deg and v < best:
                best = v
        return best

    # Kempe chain swap for (a,b) starting from vertex v
    def kempe_swap(v, a, b):
        if a == b:
            return False
        stack = [v]
        visited = set()
        comp_a = set()
        comp_b = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if color[u] == a:
                comp_a.add(u)
                for w in neighbors[u]:
                    if color[w] == b and w not in visited:
                        stack.append(w)
            elif color[u] == b:
                comp_b.add(u)
                for w in neighbors[u]:
                    if color[w] == a and w not in visited:
                        stack.append(w)
        # Check if swapping comp_a and comp_b is safe (no conflict)
        safe = True
        for u in comp_a:
            for w in neighbors[u]:
                if color[w] == b and w not in comp_b:
                    safe = False
                    break
            if not safe:
                break
        if safe:
            for u in comp_b:
                for w in neighbors[u]:
                    if color[w] == a and w not in comp_a:
                        safe = False
                        break
                if not safe:
                    break
        if not safe:
            return False
        # Perform swap
        for u in comp_a:
            color[u] = b
        for u in comp_b:
            color[u] = a
        return True

    # Main coloring loop
    for _ in range(n):
        v = select_vertex()
        if v == -1:
            break
        # Find smallest available color
        used = set()
        for u in neighbors[v]:
            if color[u] != -1:
                used.add(color[u])
        c = 0
        while c in used:
            c += 1
        color[v] = c
        # Update saturation of uncolored neighbors
        for u in neighbors[v]:
            if color[u] == -1:
                if c not in colored_neighbors[u]:
                    colored_neighbors[u].add(c)
                    sat[u] += 1

    # Kempe chain refinement to reduce colors
    max_color = max(color) if color else -1
    improved = True
    while improved and max_color > 0:
        improved = False
        # Try to eliminate color classes from highest to lowest
        for target_color in range(max_color, 0, -1):
            vertices = [v for v in range(n) if color[v] == target_color]
            if not vertices:
                continue
            # Try to recolor each vertex in this class
            for v in vertices:
                # Try direct move to lower color
                used = set()
                for u in neighbors[v]:
                    if color[u] != -1:
                        used.add(color[u])
                for c in range(target_color):
                    if c not in used:
                        color[v] = c
                        # Update saturation
                        for u in neighbors[v]:
                            if color[u] == -1:
                                if target_color not in colored_neighbors[u]:
                                    colored_neighbors[u].add(target_color)
                                    sat[u] += 1
                                if c in colored_neighbors[u]:
                                    colored_neighbors[u].remove(c)
                                    sat[u] -= 1
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chains
                for c in range(target_color):
                    if kempe_swap(v, target_color, c):
                        color[v] = c
                        # Update saturation
                        for u in neighbors[v]:
                            if color[u] == -1:
                                if target_color not in colored_neighbors[u]:
                                    colored_neighbors[u].add(target_color)
                                    sat[u] += 1
                                if c in colored_neighbors[u]:
                                    colored_neighbors[u].remove(c)
                                    sat[u] -= 1
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # Recompute max_color after potential reduction
                max_color = max(color)
                break
        if not improved:
            break

    return color

