        for i in range(n):
            neighbors = [j for j in range(n) if adj[i][j] == 1]
            adj_list.append(neighbors)
    else:
        adj_list = adj
    deg = [len(adj_list[i]) for i in range(n)]
    # Try DSATUR first
    def dsatur():
        color = [-1] * n
        saturation = [set() for _ in range(n)]
        uncolored = set(range(n))
        # Order by degree descending for initial tie-breaking in saturation
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph, then by order
            v = max(uncolored, key=lambda x: (len(saturation[x]), 
                                              sum(1 for y in adj_list[x] if y in uncolored),
                                              order.index(x)))
            # Find smallest available color
            used = {color[u] for u in adj_list[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of neighbors
            for u in adj_list[v]:
                if color[u] == -1:
                    saturation[u].add(c)
        return color
    # Try RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = []
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.append(v)
            # Partition U and W
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any(w in adj_list[u] for w in S):
                    U.remove(u)
                    W.add(u)
            # Grow S
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in G[U]
                u = max(U, key=lambda x: (sum(1 for y in adj_list[x] if y in W),
                                          -sum(1 for y in adj_list[x] if y in U)))
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
