            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    curr_deg[u] -= 1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = {color[u] for u in adj_list[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color
    # Try Welsh-Powell
    def welsh_powell():
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        color = [-1] * n
        for v in order:
            used = {color[u] for u in adj_list[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color
    # Kempe chain elimination
    def kempe_reduce(coloring):
        # Helper to get Kempe chain component for colors a,b containing v
        def kempe_component(v, a, b, col):
            if col[v] not in (a, b):
                return set()
            stack = [v]
            comp = set()
            while stack:
                u = stack.pop()
                if u in comp:
                    continue
                if col[u] not in (a, b):
                    continue
                comp.add(u)
                for w in adj_list[u]:
                    if w not in comp and col[w] in (a, b):
                        stack.append(w)
            return comp
        # Try to reduce number of colors
        max_color = max(coloring) if n > 0 else -1
        if max_color < 1:
            return coloring
        # Iterate from highest color down
        for target in range(max_color, 0, -1):
            # Vertices with color target
            verts = [v for v in range(n) if coloring[v] == target]
            if not verts:
                continue
            changed = True
            while changed and verts:
                changed = False
                for v in verts[:]:
                    if coloring[v] != target:
                        continue
                    # Try to recolor v to a lower color directly
                    for c in range(target):
                        if all(coloring[u] != c for u in adj_list[v]):
                            coloring[v] = c
                            changed = True
                            verts.remove(v)
                            break
                    if changed:
                        continue
                    # Try Kempe chains
                    for c in range(target):
                        comp = kempe_component(v, target, c, coloring)
                        # Check if inverting comp would free color target for v? Actually we want to move v to c
                        # After swap, v would become c if it was target and in comp
                        # We need that no neighbor of v becomes c after swap (i.e., no neighbor in comp colored target)
                        # Because they would become c and conflict with v's new color c.
                        conflict = False
                        for u in adj_list[v]:
                            if u in comp and coloring[u] == target:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap
                            for u in comp:
                                if coloring[u] == target:
                                    coloring[u] = c
                                else:
                                    coloring[u] = target
                            changed = True
                            if v in verts:
                                verts.remove(v)
                            break
                if changed:
                    # Rebuild verts list
                    verts = [v for v in range(n) if coloring[v] == target]
            if not verts:
                # Color target eliminated, rename higher colors down
                for v in range(n):
                    if coloring[v] > target:
                        coloring[v] -= 1
                break  # Restart from new max color
        return coloring
    # Run all candidates and pick best
    candidates = []
    for func in [dsatur, rlf, degeneracy_order, welsh_powell]:
        try:
            col = func()
            # Validate
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if col[u] == col[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                candidates.append(col)
        except Exception:
            pass
    # If no candidate, fallback to greedy
    if not candidates:
        order = list(range(n))
        color = [-1] * n
        for v in order:
            used = {color[u] for u in adj_list[v] if color[u] != -1}
            c = 0
            while c in used:
                c += 1
            color[v] = c
        candidates.append(color)
    # Apply Kempe reduction to each candidate
    reduced = []
    for col in candidates:
        try:
            col_red = kempe_reduce(col[:])  # work on copy
            # Validate again
            valid = True
            for u in range(n):
                for v in adj_list[u]:
                    if col_red[u] == col_red[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                reduced.append(col_red)
        except Exception:
            reduced.append(col)
    # Choose candidate with fewest colors
    if not reduced:
        reduced = candidates
    best = min(reduced, key=lambda x: max(x) + 1 if n > 0 else 0)
    return best

