        used_colors = saturation[v]
        c = 0
        while c in used_colors:
            c += 1
        color[v] = c
        uncolored.remove(v)

        # Update saturation sets for uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                saturation[u].add(c)

    return color

