                # But note: v itself is in component and has color target_color, but we are recoloring v.
                # So we consider neighbors u != v.
                has_conflict_after_swap = False
                for u in neighbors[v]:
                    if u == v:
                        continue
                    if color[u] == target_color:
                        if u in component:
                            # After swap, u becomes c -> conflict
                            has_conflict_after_swap = True
                            break
                    else:  # color[u] == c
                        if u not in component:
                            # After swap, u remains c -> conflict
                            has_conflict_after_swap = True
                            break
                if not has_conflict_after_swap:
                    # Perform the swap
                    for node in component:
                        if color[node] == c:
                            color[node] = target_color
                        else:  # must be target_color
                            color[node] = c
                    improved = True
                    break
            if improved:
                break
