    if k < best_k:
        best_k = k
        best_color = color[:]
    else:
        color = best_color
        k = best_k
    # Final validation (optional, but safe)
    # Ensure no adjacent same color
    for i in range(n):
        for j in neighbors[i]:
            if i < j and color[i] == color[j]:
