def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix vs list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    # Build neighbor sets
    if is_matrix:
        neighbors = [set(j for j, val in enumerate(row) if val == 1) for row in adj]
    else:
        neighbors = [set(lst) for lst in adj]
    # Ensure symmetry
    for u in range(n):
        for v in neighbors[u]:
            if u not in neighbors[v]:
                neighbors[v].add(u)
    # Helper for greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color
    # Degeneracy ordering (smallest-last)
    def degeneracy_order():
        remaining = set(range(n))
        deg = [len(neighbors[v]) for v in range(n)]
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            if deg[v] < n:
                buckets[deg[v]].append(v)
        min_deg = 0
        for _ in range(n):
            while min_deg < n and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= n:
                break
            v = buckets[min_deg].pop()
            remaining.remove(v)
            order.append(v)
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    if d < n:
                        buckets[d].remove(u)
                    deg[u] -= 1
                    if deg[u] < n:
                        buckets[deg[u]].append(u)
                    if deg[u] < min_deg:
                        min_deg = deg[u]
        return order[::-1]
    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        # Initial vertex: max degree
        v = max(range(n), key=lambda x: len(neighbors[x]))
        color[v] = 0
        colored[v] = True
        for u in neighbors[v]:
            sat[u] = 1
        for _ in range(1, n):
            # Select uncolored vertex with max saturation, tie-break by degree
            max_sat = -1
            candidates = []
            for v in range(n):
                if not colored[v]:
                    if sat[v] > max_sat:
                        max_sat = sat[v]
                        candidates = [v]
                    elif sat[v] == max_sat:
                        candidates.append(v)
            if max_sat == -1:
                break  # all colored
            # Tie-break by degree in uncolored subgraph
            v = max(candidates, key=lambda x: len([y for y in neighbors[x] if not colored[y]]))
            # Find smallest available color
            used = set()
            for u in neighbors[v]:
                if colored[u]:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            colored[v] = True
            # Update saturation of neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    # Recompute saturation degree for u
                    neighbor_colors = set()
                    for w in neighbors[u]:
                        if colored[w]:
                            neighbor_colors.add(color[w])
                    sat[u] = len(neighbor_colors)
        return color
    # RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: len([y for y in neighbors[x] if y in uncolored]))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                best_u = None
                best_score = -1
                best_deg = n+1
                for u in U:
                    score = len([w for w in neighbors[u] if w in W])
                    deg_u = len([w for w in neighbors[u] if w in U])
                    if score > best_score or (score == best_score and deg_u < best_deg):
                        best_score = score
                        best_deg = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in list(U):
                    if w in neighbors[u]:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color
    # Kempe chain swap for color reduction
    def kempe_reduce(color):
        # Find highest color used
        max_color = max(color) if n > 0 else -1
        if max_color <= 0:
            return color
        # Try to eliminate color classes from highest down
        for target in range(max_color, 0, -1):
            # Vertices with color target
            verts_target = [v for v in range(n) if color[v] == target]
            if not verts_target:
                continue
            # Try to recolor each vertex in target class
            changed = True
            while changed and verts_target:
                changed = False
                v = verts_target.pop()
                # Try to move v to a lower color directly
                for c in range(target):
                    if all(color[u] != c for u in neighbors[v]):
                        color[v] = c
                        changed = True
                        break
                if changed:
                    continue
                # Try Kempe chains with each lower color
                for c in range(target):
                    # Check if v is in a (target, c) Kempe chain that can be swapped to free c for v
                    # We do BFS to find the component of v in the subgraph of colors target and c
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    comp_color_target = set()
                    comp_color_c = set()
                    while queue:
                        x = queue.popleft()
                        if color[x] == target:
                            comp_color_target.add(x)
                        elif color[x] == c:
                            comp_color_c.add(x)
                        for y in neighbors[x]:
                            if y not in visited and (color[y] == target or color[y] == c):
                                visited.add(y)
                                queue.append(y)
                    # If no vertex in component has color c, we can swap
                    if not comp_color_c:
                        # Swap colors target <-> c in the component
                        for x in comp_color_target:
                            color[x] = c
                        changed = True
                        break
            if not changed:
                # Cannot reduce further
                break
        return color
    # Try multiple orders and methods
    best_color = None
    best_colors_used = float('inf')
    # Order 1: Degeneracy (smallest-last)
    order1 = degeneracy_order()
    color1 = greedy_color(order1)
    colors_used1 = max(color1) + 1 if n > 0 else 0
    if colors_used1 < best_colors_used:
        best_colors_used = colors_used1
        best_color = color1[:]
    # Order 2: DSATUR
    color2 = dsatur()
    colors_used2 = max(color2) + 1 if n > 0 else 0
    if colors_used2 < best_colors_used:
        best_colors_used = colors_used2
        best_color = color2[:]
    # Order 3: RLF
    color3 = rlf()
    colors_used3 = max(color3) + 1 if n > 0 else 0
    if colors_used3 < best_colors_used:
        best_colors_used = colors_used3
        best_color = color3[:]
    # Apply Kempe reduction to the best so far
    color_reduced = kempe_reduce(best_color[:])
    colors_used_reduced = max(color_reduced) + 1 if n > 0 else 0
    if colors_used_reduced < best_colors_used:
        best_colors_used = colors_used_reduced
        best_color = color_reduced[:]
    # Final greedy improvement: try to reorder by saturation and recolor
    def improve(color):
        # Try to reduce number of colors by reassigning via DSATUR-like but with current color as guide
        # We attempt to recolor using the current color order but allow lowering
        # Simple: for each vertex in random order, try to assign smallest possible color
        order = list(range(n))
        random.shuffle(order)
        new_color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if new_color[u] != -1:
                    used.add(new_color[u])
            c = 0
            while c in used:
                c += 1
            new_color[v] = c
        # If uses same or fewer colors, consider
        used_colors = max(new_color) + 1 if n > 0 else 0
        if used_colors <= best_colors_used:
            return new_color
        return color
    # Run a few iterations of improvement
    for _ in range(10):
        improved = improve(best_color)
        used_improved = max(improved) + 1 if n > 0 else 0
        if used_improved < best_colors_used:
            best_colors_used = used_improved
            best_color = improved
    return best_color

