                saturation[u].add(c)
                uncolored_deg[u] -= 1

    # Kempe chain refinement to reduce color count
    max_color = max(color) if n > 0 else 0
    # Try to reduce from max_color down to 1
    for target_color in range(max_color, 0, -1):
        # Collect vertices with color target_color
        verts_target = [i for i in range(n) if color[i] == target_color]
        if not verts_target:
            continue  # already missing, try next lower
        # Try to recolor each vertex in verts_target to a lower color
        success = True
        for v in verts_target:
            # Try direct move to a lower color
            moved = False
            for c in range(target_color):
                # Check if color c is available (no neighbor has color c)
                conflict = False
                for u in adj_list[v]:
                    if color[u] == c:
                        conflict = True
                        break
                if not conflict:
                    # Move v to color c
                    color[v] = c
                    moved = True
                    break
            if moved:
                continue
            # Try Kempe chain swap for each lower color c
            kempe_success = False
            for c in range(target_color):
                # If v already has a neighbor with color c, swapping might not help directly
                # But we check if there is a Kempe chain (v, target_color) that does not connect to any c-colored vertex
                # BFS to get the (target_color, c)-Kempe chain component containing v
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                has_c_neighbor = False  # whether component has a neighbor with color c (outside)
                while queue:
                    node = queue.popleft()
                    component.append(node)
                    for nb in adj_list[node]:
                        if color[nb] == target_color or color[nb] == c:
                            if not visited[nb]:
                                visited[nb] = True
                                queue.append(nb)
                        elif color[nb] == c:
                            # Found a neighbor with color c adjacent to the component
                            has_c_neighbor = True
                # If the component does not have any adjacent vertex with color c, we can swap
                if not has_c_neighbor:
                    # Swap colors target_color and c in the component
                    for node in component:
                        if color[node] == target_color:
                            color[node] = c
                        elif color[node] == c:
                            color[node] = target_color
                    kempe_success = True
                    break
            if not kempe_success:
                success = False
                break
        if success:
            # All vertices of target_color have been recolored, so we can reduce max_color
            # Actually, we have reassigned them, so target_color is no longer used
            # But we continue to try lower target_color in the outer loop
            pass
        else:
            # Failed to eliminate target_color, break and keep current coloring
            break

    return color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary 0/1)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
        deg = [len(adj_list[i]) for i in range(n)]
    else:
        adj_list = adj
        deg = [len(adj_list[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid(colors):
        for u in range(n):
            cu = colors[u]
            for v in adj_list[u]:
                if colors[v] == cu:
                    return False
        return True

    # Helper: count number of colors used
    def num_colors(colors):
        if not colors:
            return 0
        return max(colors) + 1

    # DSATUR implementation
    def dsatur():
        colors = [-1] * n
        # saturation: list of sets of neighbor colors for each vertex
        saturation = [set() for _ in range(n)]
        # uncolored set
        uncolored = set(range(n))
        # current max color used
        max_color_used = -1

        while uncolored:
            # select vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat_v = len(saturation[v])
                # degree in uncolored subgraph: count uncolored neighbors
                deg_uncolored = 0
                for nb in adj_list[v]:
                    if nb in uncolored:
                        deg_uncolored += 1
                if sat_v > best_sat or (sat_v == best_sat and deg_uncolored > best_deg) or (sat_v == best_sat and deg_uncolored == best_deg and v > best_v):
                    best_sat = sat_v
                    best_deg = deg_uncolored
                    best_v = v
            v = best_v

            # find smallest color not used by neighbors
            used = set()
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            if c > max_color_used:
                max_color_used = c
            uncolored.remove(v)

            # update saturation of uncolored neighbors
            for nb in adj_list[v]:
                if nb in uncolored:
                    saturation[nb].add(c)
        return colors

    # RLF implementation
    def rlf():
        colors = [-1] * n
        uncolored = set(range(n))
        color_idx = 0

        while uncolored:
            # Step 1: pick vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            for u in uncolored:
                deg_uncolored = 0
                for nb in adj_list[u]:
                    if nb in uncolored:
                        deg_uncolored += 1
                if deg_uncolored > max_deg:
                    max_deg = deg_uncolored
                    v = u
            # Start independent set S with v
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent_to_S = False
                for w in S:
                    if u in adj_list[w]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)

            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # score: number of neighbors in W
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # degree in G[U]
                    deg_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or (score == best_score and deg_U == best_deg_U and u < best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                # add u to S
                S.add(u)
                U.remove(u)
                # move neighbors of u that are in U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color_idx to all in S
            for vertex in S:
                colors[vertex] = color_idx
            # remove S from uncolored
            uncolored -= S
            color_idx += 1
        return colors

    # Welsh-Powell (degree ordering) greedy
    def welsh_powell():
        order = sorted(range(n), key=lambda x: deg[x], reverse=True)
        colors = [-1] * n
        for v in order:
            used = set()
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    # Smallest-Last ordering
    def smallest_last():
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = deg[:]  # current degree in remaining subgraph
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            buckets[d].append(v)
        # pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # find next non-empty bucket
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            # remove v
            remaining.remove(v)
            order.append(v)
            # update neighbors
            for nb in adj_list[v]:
                if nb in remaining:
                    d = degree[nb]
                    # remove nb from bucket d
                    if nb in buckets[d]:
                        buckets[d].remove(nb)
                    degree[nb] -= 1
                    d_new = degree[nb]
                    if d_new < len(buckets):
                        buckets[d_new].append(nb)
                    else:
                        # extend buckets if needed (should not happen as degree decreases)
                        while len(buckets) <= d_new:
                            buckets.append([])
                        buckets[d_new].append(nb)
                    if d_new < min_deg:
                        min_deg = d_new
        # color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        return colors

    # Kempe chain swap for color class reduction
    def kempe_reduce(colors):
        k = num_colors(colors)
        if k <= 1:
            return colors
        # target color to eliminate: k-1
        target = k - 1
        # vertices with target color
        target_vertices = [v for v in range(n) if colors[v] == target]
        # try to recolor each target vertex
        for v in target_vertices:
            # colors used by neighbors
            neighbor_colors = set()
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    neighbor_colors.add(colors[nb])
            # try to find a color c < target that is not used by neighbors
            for c in range(target):
                if c not in neighbor_colors:
                    colors[v] = c
                    break
            else:
                # try Kempe chains for each c < target
                for c in range(target):
                    if c in neighbor_colors:
                        continue
                    # Actually, we need to check if we can swap along a Kempe chain (v, target) with color c
                    # We want to see if we can swap colors target and c in the component containing v
                    # such that v becomes c and no conflict arises.
                    # But standard: if v cannot take c because neighbor has c, we look at the Kempe chain of c and target starting from that neighbor.
                    # However, we implement: try to move v to c via Kempe chain if possible.
                    # Build the Kempe chain component for colors (c, target) that contains v.
                    # We'll do BFS/DFS over vertices with color c or target.
                    from collections import deque
                    visited = set()
                    queue = deque([v])
                    visited.add(v)
                    component = set()
                    while queue:
                        x = queue.popleft()
                        component.add(x)
                        for nb in adj_list[x]:
                            if nb not in visited and (colors[nb] == c or colors[nb] == target):
                                visited.add(nb)
                                queue.append(nb)
                    # Check if any neighbor of v in the component has color c? Actually, we want to see if we can swap without conflict.
                    # After swapping, v will become c. We need to ensure no neighbor of v has color c after swap.
                    # After swap, vertices in component: if was c becomes target, if was target becomes c.
                    # So neighbors of v that are in component: if they were c, they become target (ok, since v becomes c, and target != c)
                    # if they were target, they become c -> conflict if neighbor of v becomes c and v becomes c.
                    # Therefore, we need that no neighbor of v is in the component and has color target (because after swap it becomes c).
                    # Actually, simpler: after swap, the color of v becomes c. So we need that no neighbor of v has color c after swap.
                    # After swap, a neighbor u of v:
                    #   if u not in component: color unchanged.
                    #   if u in component: 
                    #       if was c -> becomes target
                    #       if was target -> becomes c
                    # So conflict if:
                    #   (u not in component and colors[u] == c) OR (u in component and colors[u] == target)
                    # We can check: for each neighbor u of v:
                    #   if (u not in component and colors[u] == c) or (u in component and colors[u] == target):
                    #       then conflict.
                    conflict = False
                    for nb in adj_list[v]:
                        if nb in component:
                            if colors[nb] == target:  # after swap becomes c
                                conflict = True
                                break
                        else:
                            if colors[nb] == c:  # unchanged
                                conflict = True
                                break
                    if not conflict:
                        # perform swap
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target
                            else:  # must be target
                                colors[x] = c
                        colors[v] = c  # actually v is in component and was target, now becomes c
                        break
                else:
                    # could not recolor v, keep target color
                    pass
        # after attempting to recolor all target vertices, check if target color is still used
        if target not in set(colors):
            # target color eliminated, recurse? but we just return new coloring with possibly lower k
            # Actually, we return the colors array which may have max color < target
            pass
        return colors

    # Main: try multiple methods and keep best valid coloring
    best_colors = None
    best_k = float('inf')

    # List of coloring functions to try
    coloring_funcs = [
        dsatur,
        rlf,
        welsh_powell,
        smallest_last
    ]

    for func in coloring_funcs:
        try:
            colors = func()
            if is_valid(colors):
                k = num_colors(colors)
                if k < best_k:
                    best_k = k
                    best_colors = colors[:]
        except Exception:
            continue

    # If no valid coloring found (should not happen), fallback to trivial
    if best_colors is None:
        # greedy in order 0..n-1
        colors = [-1] * n
        for v in range(n):
            used = set()
            for nb in adj_list[v]:
                if colors[nb] != -1:
                    used.add(colors[nb])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_colors = colors

    # Apply Kempe reduction iteratively a few times to try to improve
    for _ in range(2):  # limited iterations for speed
        new_colors = kempe_reduce(best_colors)
        if is_valid(new_colors):
            k_new = num_colors(new_colors)
            if k_new < best_k:
                best_k = k_new
                best_colors = new_colors[:]
        else:
            break

    return best_colors
